package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observeddashboard.domain.Panels;

class PanelsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property panels of observed dashboard ")
  void test_panels_v_o_builder() {
    Assertions.assertTrue(PanelsVO.tryFrom(null).getPanels().isEmpty());
    List<Panels> list = List.of();
    Assertions.assertEquals(list, PanelsVO.from(list).getPanels());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> PanelsVO.tryFrom(falingInstance));
    Assertions.assertEquals(
        "[" + List.of(Panels.builder().uid("one").title("one").description("one").chartType("one")
            .query("one").options("one").x(1).y(1).w(1).h(1).version(1).build()) + "]",
        PanelsVO
            .from(
                List.of(Panels.builder().uid("one").title("one").description("one").chartType("one")
                    .query("one").options("one").x(1).y(1).w(1).h(1).version(1).build()))
            .toString());
  }
}
